&lt;span class="k"&gt;this&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="nf"&gt;handleRouteChange&lt;/span&gt;&lt;span class="p"&gt;();&lt;/span&gt;
